engine.filterRulesByType:
function filterRulesByType(allRules, docType) {
  if (!Array.isArray(allRules)) return [];
  var detected = String(docType || "").toLowerCase();
  return allRules.filter(function (r) {
    if (!r || r.enabled === false) return false;
    var types = r.agreementTypes || (r.type ? [r.type] : []);
    if (!Array.isArray(types) || !types.length) return true; // unrestricted
    var universal = types.some(function (t) {
      return String(t).toLowerCase().indexOf("all") !== -1;
    });
    if (universal) return true;
    // Build alias bag from each type. Tokens >2 chars only — strips
    // glue words like "of", "and".
    var aliases = [];
    types.forEach(function (t) {
      var s = String(t).toLowerCase().trim();
      aliases.push(s);
      s.split(/[\s,/&]+/).forEach(function (w) {
        if (w.length > 2) aliases.push(w);
      });
    });
    return aliases.some(function (alias) {
      return detected.indexOf(alias) !== -1 || alias.indexOf(detected) !== -1;
    });
  });
}

