  // ─── Wire interactions ───────────────────────────────────────────
  // Overview collapse toggle.
  var overviewHead = root.querySelector('[data-toggle="overview"]');
  overviewHead.onclick = function () {
    var body = root.querySelector("#_eli3_lr_overview_body");
    var arrow = root.querySelector("#_eli3_lr_overview_arrow");
    var hint = root.querySelector("#_eli3_lr_overview_hint");
    if (!body) return;
    var isHidden = body.hasAttribute("hidden");
    if (isHidden) {
      body.removeAttribute("hidden");
      arrow.textContent = "▼";
      hint.style.opacity = "0";
    } else {
      body.setAttribute("hidden", "");
      arrow.textContent = "◀";
      hint.style.opacity = "1";
    }
  };

  // Section collapse toggle.
  var sectionHead = root.querySelector('[data-toggle="section"]');
  sectionHead.onclick = function () {
    var body = root.querySelector("#" + sectionId);
    var arrow = root.querySelector("#_eli3_lr_results_section_arrow");
    if (!body) return;
    var isHidden = body.hasAttribute("hidden");
    if (isHidden) {
      body.removeAttribute("hidden");
      arrow.textContent = "▼";
    } else {
      body.setAttribute("hidden", "");
      arrow.textContent = "◀";
    }
  };

  // Per-card action buttons — delegate so the row's interactive
  // elements don't compete with the section-collapse handler. The
  // "fix" data-action splits into onFix vs onDelete based on the
  // button's _delete CSS class (set when AI's fix_suggestion is a
  // deletion verb) — keeps the v2 separation while sharing the
  // attribute.
  Array.prototype.forEach.call(root.querySelectorAll("[data-action]"), function (btn) {
    btn.onclick = function (ev) {
      ev.stopPropagation();
      var idx = Number(btn.getAttribute("data-idx"));
      var item = combined[idx];
      if (!item) return;
      var action = btn.getAttribute("data-action");
      if (action === "locate") onLocate(item, btn);
      else if (action === "fix") {
        if (btn.classList.contains("_eli3_lr_results_btn_delete")) onDelete(item, btn);
        else onFix(item, btn);
      }
      else if (action === "dismiss") {
        onDismiss(item, btn);
        var card = root.querySelector("#_eli3_lr_card_" + idx);
        if (card && card.parentNode) card.parentNode.removeChild(card);
      }
    };
  });

  // Header close + footer Home — both go home. Speed-reader easter
  // egg (v2 line 50): if user closes within 3 seconds of render,
  // fire the trophy hook. Useful telemetry — "scanned + decided fast"
  // is a recognizable pattern that maps to a real achievement.
  function _onClose() {
    if (Date.now() - renderTs < 3000) {
      try { onCloseFast(); } catch (e) {}
    }
    onHome();
  }
  root.querySelector("._eli3_lr_results_close").onclick = _onClose;
  root.querySelector("._eli3_lr_results_home").onclick = _onClose;

  return {
    refresh: function () {
      // Caller re-runs renderResults for a fresh paint. Cheaper than
      // diffing — the page is shallow.
    },
  };
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["legal_risks"];
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var analyze       = efns.analyze;
  var renderResults = vfns.renderResults;
  if (!analyze || !renderResults) {
    eli.log.event("tool", "legal_risks_load_failed", {
      hasAnalyze: !!analyze, hasView: !!renderResults,
    });
    return;
  }

  // ─── Doc-hash helper (matches build_draft + ask_eli shape) ────────
  function _hashContent(text) {
    if (!text) return "empty";
    var s = String(text), hash = 0;
    for (var i = 0; i < s.length; i++) {
      hash = ((hash << 5) - hash) + s.charCodeAt(i);
      hash |= 0;
    }
    return "h" + (hash >>> 0).toString(36);
  }

  // ─── Load risk rules from IDB ─────────────────────────────────────
  // STORE_RISK_RULES = "risk_rules" — populated by risk_rules_manager
  // tool + the __data_risk_rules data bundle.
  function _loadRules() {
    if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve([]);
    return eli.storage.getAll("risk_rules").then(function (rows) {
      return (rows || []).filter(function (r) {
        return r && r.id && String(r.id).charAt(0) !== "_";
      });
    }).catch(function () { return []; });
  }

  // ─── Read doc text (with stable per-paragraph anchors) ────────────
  // FROM v2 getLegalTextWithAnchors. v3 host exposes
  // readTextWithAnchors which inserts bookmarks named `_ELI_LR_<i>`
  // and returns [{id, text}, ...]. We flatten back to a single text
  // string for the AI prompt; the bookmarks stay in the doc for the
  // LOCATE button to scroll to clauses later.
  function _readDocText() {
    if (!eli.host || typeof eli.host.readTextWithAnchors !== "function") {
      // Fallback — plain text read.
      if (eli.host && typeof eli.host.readText === "function") {
        return eli.host.readText().then(function (t) { return { text: t || "", anchors: [] }; });
      }
      return Promise.resolve({ text: "", anchors: [] });
    }
    return eli.host.readTextWithAnchors({ prefix: "_ELI_LR_", minLen: 5 }).then(function (anchors) {
      anchors = anchors || [];
      // Pass anchors as a JSON array of {id, text} — the prompt template
      // (data/prompts.json → legalRisksReview) explicitly tells the AI:
      // "Use the EXACT 'id' property from the provided JSON array (e.g.
      // '_ELI_LR_5'). Do NOT invent an id." Pre-fix this was being
      // flattened to a plain string, so the AI never saw IDs and LOCATE
      // had no anchor to jump to. (Bug fix 2026-05-11.)
      var text = JSON.stringify(anchors);
      return { text: text, anchors: anchors };
    }).catch(function () {
      return { text: "", anchors: [] };
    });
  }

  // ─── Locate a clause in the document ──────────────────────────────
  // LOCATE button handler. Single source of truth — the engine's
  // normalize step ALWAYS sets item.id to a `_ELI_LR_<n>` bookmark
  // name (or null if AI didn't return one). We jump straight to the
  // bookmark via eli.host.highlightAnchor.
  //
  // No text-search fallback — per design: indexing happens at scan
  // start (eli.host.readTextWithAnchors inserts every paragraph as
  // _ELI_LR_<n>); the AI gets the JSON array of {id, text}; the AI
  // returns the matching id. If LOCATE can't find the bookmark, that
  // means either (a) the AI didn't follow instructions and returned
  // a bad id (engine logs via wrongness capture), or (b) the user
  // edited the doc enough to wipe bookmarks. Both should fail loudly,
  // not silently fall back to fuzzy text search.
  function _locateClause(item) {
    var anchorId = String(item.id || "").trim();
    if (!anchorId || anchorId.indexOf("_ELI_LR_") !== 0) {
      if (typeof showToast === "function") {
        showToast("No paragraph anchor for this clause — AI didn't return id (open Wrongness Viewer to inspect).", "warn");
      }
      return Promise.resolve(false);
    }
    if (!eli.host || typeof eli.host.highlightAnchor !== "function") {
      if (typeof showToast === "function") showToast("eli.host.highlightAnchor unavailable.", "err");
      return Promise.resolve(false);
    }
    return eli.host.highlightAnchor(anchorId).then(function () {
      return true;
    }).catch(function (err) {
      if (typeof showToast === "function") {
        showToast("Bookmark " + anchorId + " not found — re-run scan to refresh anchors.", "warn");
      }
      eli.log.event("tool", "legal_risks_locate_anchor_missing", {
        anchor: anchorId, msg: err && err.message,
      });
      return false;
    });
  }

  // ─── FIX button — surgical redline ────────────────────────────────
  // Routes through the kernel-level eli.host.applySurgicalRedline
  // helper (apiVersion 2). Behavior:
  //   1. Show a preview dialog: side-by-side original + suggested.
  //   2. On user confirm: select target text in the doc (visual cue),
  //      then apply surgical redline.
  //   3. On rangeNotFound: surface coarse-replace fallback toast.
  //
  // The suggestion might be a verb like "delete clause" (handled
  // separately by _deleteClause). For a textual rewrite, the AI's
  // fix_suggestion can be either a complete replacement OR an
  // instructive sentence ("Rewrite to limit liability to fees paid").
  // Heuristic: if the suggestion contains a verb prefix like
  // "rewrite" or "consider", treat as instruction and pass through
  // to ask_eli for AI-generated rewrite; otherwise apply literally.
  function _fixClause(item) {
    var original = String(item.text || "").trim();
    var suggestion = String(item.fix_suggestion || "").trim();
    if (!original) {
      if (typeof showToast === "function") showToast("No original text to fix.", "warn");
      return;
    }
    if (!suggestion) {
      if (typeof showToast === "function") showToast("AI provided no rewrite suggestion.", "warn");
      return;
    }
    // Instruction-style suggestion → defer to ask_eli for AI rewrite.
    var instructionRx = /^(rewrite|revise|consider|recommend|amend|modify|update|change|reword|negotiate|propose)\b/i;
    if (instructionRx.test(suggestion)) {
      var askEliCompose = eli.get && eli.get("ask_eli", "compose");
      if (typeof askEliCompose === "function") {
        try {
          askEliCompose({
            question: suggestion + " — apply with track changes.",
            context: [
              { role: "user", content: "Rewrite this clause:\n\n" + original },
              { role: "model", content: "Recommendation: " + suggestion },
            ],
          });
          return;
        } catch (e) { /* fall through to preview dialog */ }
      }
    }
    // Literal replacement candidate — preview + confirm + apply.
    if (typeof showEliDialog !== "function") {
      _applySurgicalNow(original, suggestion);
      return;
    }
    showEliDialog({
      variant: "info",
      tier: "premium",
      icon: "⚡",
      title: "Proposed Rewrite",
      body:
        '<div style="font-size:11px; color:#64748b; text-transform:uppercase; letter-spacing:0.4px; margin-bottom:6px;">Original</div>' +
        '<div style="background:#f8fafc; padding:10px; border-left:3px solid #c62828; font: 500 12px/1.5 Georgia, serif; color:#475569; margin-bottom:14px;">' +
          String(original).replace(/&/g, "&amp;").replace(/</g, "&lt;") +
        '</div>' +
        '<div style="font-size:11px; color:#1565c0; text-transform:uppercase; letter-spacing:0.4px; margin-bottom:6px;">Suggested</div>' +
        '<div style="background:#fff8e1; padding:10px; border-left:3px solid #1565c0; font: 500 12px/1.5 Georgia, serif; color:#0f172a;">' +
          String(suggestion).replace(/&/g, "&amp;").replace(/</g, "&lt;") +
        '</div>',
      primary: {
        label: "⚡ Apply with track changes",
        onclick: function (e, overlay) {
          _applySurgicalNow(original, suggestion);
        },
      },
      secondary: { label: "Cancel" },
    });
  }

  // Run the kernel-level surgical redline + surface result toast.
  // Falls back to ask_eli's action-card path on coarse-replace (range
  // not found) so the user always has a path forward.
  function _applySurgicalNow(originalText, newText) {
    if (!eli.host || typeof eli.host.applySurgicalRedline !== "function") {
      // Kernel doesn't have the helper yet — fall back to ask_eli.
      var askEliCompose = eli.get && eli.get("ask_eli", "compose");
      if (typeof askEliCompose === "function") {
        try {
          askEliCompose({
            question: "Apply this rewrite with track changes.",
            context: [
              { role: "user", content: "Rewrite this clause:\n\n" + originalText },
              { role: "model", content: newText },
            ],
          });
          return;
        } catch (e) {}
      }
      if (typeof showToast === "function") showToast("Surgical apply requires kernel update (paste latest taskpane_v3.js).", "warn");
      return;
    }
    if (typeof showToast === "function") showToast("⚡ Applying with track changes…", "info");
    eli.host.applySurgicalRedline({
      originalText: originalText,
      newText: newText,
      preserveFormatting: true,
    }).then(function (res) {
      if (!res) return;
      if (res.precision === "minimal") {
        if (typeof showToast === "function") showToast("✓ Applied with surgical track changes.", "ok");
      } else if (res.precision === "noop") {
        if (typeof showToast === "function") showToast("✓ No change — rewrite matches original.", "info");
      } else {
        // Coarse — range not found. Offer a manual review path.
        if (typeof showToast === "function") {
          showToast("Couldn't pinpoint the clause — try LOCATE first, then re-run FIX.", "warn");
        }
      }
    }).catch(function (err) {
      eli.log.event("tool", "legal_risks_apply_failed", { msg: err && err.message });
      if (typeof showToast === "function") showToast("Apply failed: " + (err && err.message || "unknown"), "err");
    });
  }

  // DELETE — surgical empty-replace via the same kernel helper.
  function _deleteClause(item) {
    var original = String(item.text || "").trim();
    if (!original) {
      if (typeof showToast === "function") showToast("No clause text to delete.", "warn");
      return;
    }
    if (typeof showEliDialog === "function") {
      showEliDialog({
        variant: "danger",
        icon: "🗑️",
        title: "Delete this clause?",
        body: '<div style="font: 500 12px/1.5 Georgia, serif; color:#475569; background:#fef2f2; padding:10px; border-left:3px solid #c62828;">' +
          String(original).replace(/&/g, "&amp;").replace(/</g, "&lt;") + '</div>',
        primary: {
          label: "🗑️ Delete with track changes",
          onclick: function () { _applySurgicalNow(original, ""); },
        },
        secondary: { label: "Cancel" },
      });
    } else {
      _applySurgicalNow(original, "");
    }
  }

  // ─── DISMISS — track in session feed ──────────────────────────────
  function _dismissItem(item) {
    if (eli.activity && eli.activity.add) {
      try {
        eli.activity.add({
          type: "legal-360-dismiss",
          icon: "✕",
          label: "Risk Dismissed",
          summary: String(item.title || "Risk").substring(0, 80),
          payload: { title: item.title, clauseRef: item.clause_ref },
        });
      } catch (e) {}
    }
  }

  // ─── Pre-scan redlines guard (FROM v2 checkRedlinesBeforeScan) ────
  // When the doc has tracked changes, the scan analyzes the text
  // AS-IF all redlines were accepted (which is what users actually
  // want — but it's worth confirming because the result reflects a
  // hypothetical doc state, not the literal text on screen).
  // Returns Promise<boolean> — true to continue scanning, false to
  // bail. Skips the confirm when no redlines are present.
  function _checkRedlinesBeforeScan() {
    if (!eli.host || typeof eli.host.runRaw !== "function") return Promise.resolve(true);
    return eli.host.runRaw("legal_risks:redline_check", function (context) {
      var changes = context.document.body.getTrackedChanges();
      changes.load("items");
      return context.sync().then(function () {
        return (changes.items || []).length;
      });
    }).catch(function () { return 0; }).then(function (n) {
      if (!n) return true;
      if (typeof eli.ui === "undefined" || typeof eli.ui.confirm !== "function") return true;
      return eli.ui.confirm({
        title: n + " tracked change" + (n === 1 ? "" : "s") + " in this doc",
        message:
          "The risk scan analyzes the document as if all redlines were already accepted. " +
          "Risks flagged reflect the hypothetical post-accept state, not the literal text on screen.",
        confirmLabel: "Scan anyway",
        cancelLabel: "Cancel",
        variant: "info",
      });
    });
  }

  // ─── Open the scan UI ─────────────────────────────────────────────
  function _open(preloadOpts) {
    preloadOpts = preloadOpts || {};
    if (!eli.ai || typeof eli.ai.hasApiKey !== "function" || !eli.ai.hasApiKey()) {
      if (typeof showToast === "function") showToast("Set a Gemini API key in Settings → Global first.", "warn");
      if (eli.settings && typeof eli.settings.show === "function") eli.settings.show();
      return;
    }
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) {
      eli.log.event("tool", "legal_risks_open_no_mount", {});
      if (typeof showToast === "function") showToast("Dashboard root missing — try reopening ELI", "err");
      return;
    }

    // FROM v2: when redlines are present, the scan still runs but
    // we surface a one-shot confirm so the user knows. Skipping a
    // confirm with `--yes`-style launcher flag is supported.
    var launcherCfg = (typeof window !== "undefined" && window._legalRisksLauncherSettings) || {};
    var skipGuard = launcherCfg.skipRedlineGuard === true;
    (skipGuard ? Promise.resolve(true) : _checkRedlinesBeforeScan()).then(function (proceed) {
      if (!proceed) return;
      _runScan(preloadOpts, launcherCfg);
    });
  }

  function _runScan(preloadOpts, launcherCfg) {
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) return;
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedRisk"); } catch (e) {}
    try {
      var cur = eli.fsm.getCurrent ? eli.fsm.getCurrent() : null;
      if (cur === "idle") eli.fsm.transition("scanning");
    } catch (e) {}

    // Show a loading overlay while the AI runs.
    if (typeof setLoading === "function") {
      try { setLoading(true, "legal"); } catch (e) {}
    }

    var showUsage = launcherCfg.showUsage !== false;
    var docType = (typeof window !== "undefined" && window._eliDocType) || preloadOpts.docType || "";
    var scanStartTs = Date.now();

    Promise.all([
      _readDocText(),
      _loadRules(),
    ]).then(function (r) {
      var doc = r[0];
      var rules = r[1];
      eli.log.event("tool", "legal_risks_input_ready", {
        textLen: (doc.text || "").length,
        anchors: (doc.anchors || []).length,
        rulesAvailable: rules.length,
      });
      var _engineInput = {
        text: doc.text,
        rules: rules,
        docType: docType,
        showUsage: showUsage,
        docHash: _hashContent(doc.text),
      };
      return analyze(_engineInput, { ai: eli.ai, host: eli.host, storage: eli.storage }).then(function (result) {
        if (eli.wrongness) eli.wrongness.capture("legal_risks", _engineInput, result, {});
        return result;
      });
    }).then(function (result) {
      try { if (eli.stats && eli.stats.record) eli.stats.record("docsReviewed"); } catch (e) {}
      if (result.items && result.items.length) {
        try { eli.stats.record("risksFound", result.items.length); } catch (e) {}
      }
      if (typeof setLoading === "function") {
        try { setLoading(false); } catch (e) {}
      }
      try { eli.fsm.transition("rendering"); } catch (e) {}

      renderResults({
        mount: mount,
        data: result,
        rulesActive: result.rulesActive,
        showUsage: showUsage,
        onHome: function () {
          try { eli.fsm.transition("idle"); } catch (e) {}
          if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
        },
        onLocate: function (item) { _locateClause(item); },
        onFix:    function (item) { _fixClause(item); },
        onDelete: function (item) { _deleteClause(item); },
        onDismiss: function (item) { _dismissItem(item); },
        // Speed-reader easter egg: closing the results within 3s of
        // render counts as a "speed_reader" trophy event. Trophy
        // gallery's queue handler dedups per session so it can't
        // re-fire on the same trophy id.
        onCloseFast: function () {
          try { eli.dispatch && eli.dispatch("trophies", "unlocked", {
            id: "speed_reader",
            icon: "⚡",
            title: "Speed Reader",
            desc: "Closed Legal Risks within 3 seconds of opening.",
          }); } catch (e) {}
        },
      });

      // FROM v2: deal360 quirky trophy — fires when a scan finds risks +
      // counts the number of "defined terms" the AI's text contains.
      // Pattern: "Capitalized (?= shall mean | means | is defined as)".
      try {
        var rCount = (result.items || []).filter(function (i) { return i.category === "Risk"; }).length;
        var tMatch = (result.raw && result.raw._docTextForCount) ||
          (typeof doc !== "undefined" && doc.text) || "";
        var defined = String(tMatch).match(/[A-Z][a-z]+(?=\s+(?:means|shall mean|is defined as))/g);
        var tCount = defined ? new Set(defined).size : 0;
        if (rCount > 0 || tCount > 0) {
          eli.dispatch && eli.dispatch("trophies", "unlocked", {
            id: "deal360",
            icon: "📊",
            title: "Deal 360°",
            desc: "Scanned a document with the Legal Risks engine.",
            riskCount: rCount,
            termCount: tCount,
          });
        }
      } catch (e) {}

      // FROM v2: Compare integration. When the launcher passed a
      // comparePayload (third-party paper with matched template/version),
      // ALSO run the Compare flow and render its results into the
      // `lrlCompareTarget` div below the risk cards.
      if (launcherCfg && launcherCfg.comparePayload && eli.get) {
        var compareHandler = eli.get("compare", "version");
        if (typeof compareHandler === "function") {
          try {
            compareHandler({
              payload: launcherCfg.comparePayload,
              mode: launcherCfg.compareMode || "new",
              target: document.getElementById("_eli3_lr_compare_target"),
            });
          } catch (e) {
            eli.log.event("tool", "legal_risks_compare_handoff_failed", { msg: e && e.message });
          }
        }
        // One-shot — don't re-run on next scan.
        try { delete launcherCfg.comparePayload; } catch (e) {}
      }

      // Activity feed — restorable entry so clicking re-renders this view.
      var summary;
      if (!result.items || !result.items.length) {
        summary = "✅ No risks detected";
      } else {
        var parts = [];
        if (result.riskCount) parts.push(result.riskCount + " Risk" + (result.riskCount !== 1 ? "s" : ""));
        if (result.usageCount) parts.push(result.usageCount + " Ops");
        summary = parts.join(" · ") + " detected";
      }
      var durationMs = Date.now() - scanStartTs;
      if (eli.activity && eli.activity.add) {
        try {
          eli.activity.add({
            type: "legal-360",
            icon: "⚡",
            label: "Legal Risks",
            summary: summary,
            payload: result,
            durationMs: durationMs,
            provenance: result.provenance,
            restoreChannel: "activity_restore",
            restoreKey: "legal-360",
          });
        } catch (e) {}
      }
    }).catch(function (err) {
      if (typeof setLoading === "function") {
        try { setLoading(false); } catch (e) {}
      }
      eli.log.event("tool", "legal_risks_open_failed", { msg: err && err.message });
      if (err && err.message && /abort|cancel/i.test(err.message)) {
        if (typeof showCancelledState === "function") showCancelledState();
        return;
      }
      if (typeof showToast === "function") {
        showToast("Analysis failed: " + (err && err.message || "unknown"), "err");
      }
    });
  }

  // ─── Activity-feed restore — re-renders a past Legal Risks result ─
  function _restoreActivity(payload) {
    if (!payload) return;
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) {
      if (typeof showToast === "function") showToast("Dashboard root missing", "err");
      return;
    }
    try { eli.fsm.transition("rendering"); } catch (e) {}
    // payload may be the result object OR the wrapper with .items.
    var data = (payload && payload.items) ? payload : (payload.raw || { items: [] });
    // Optional section filter — caller passes `payload.sectionLabel`
    // to render only risks attached to a particular section
    // (selection-panel "Scan this section" flow). When set, we filter
    // items via the engine helper before painting.
    if (payload && payload.sectionLabel && Array.isArray(data.items)) {
      data = Object.assign({}, data, {
        items: _filterItemsForSection(data.items, payload.sectionLabel),
      });
    }
    var rulesActive = !!(payload.rulesActive || (payload.raw && payload.raw._rulesWereActive));
    renderResults({
      mount: mount,
      data: data,
      rulesActive: rulesActive,
      showUsage: true,
      onHome: function () {
        try { eli.fsm.transition("idle"); } catch (e) {}
        if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
      },
      onLocate: function (item) { _locateClause(item); },
      onFix:    function (item) { _fixClause(item); },
      onDelete: function (item) { _deleteClause(item); },
      onDismiss: function (item) { _dismissItem(item); },
    });
  }

  // ─── Section filter helper (FROM v2 legalRisksFilterForSection) ───
  // Filter a Legal Risks items list down to entries that reference
  // the supplied section label. Loose match — substring either way
  // because the AI sometimes uses different naming conventions for
  // the section ("Confidentiality", "Section 5", "Article 5.2", etc.)
  // and the caller might pass any of those forms.
  function _filterItemsForSection(items, sectionLabel) {
    if (!Array.isArray(items)) return [];
    var sLow = String(sectionLabel || "").toLowerCase();
    if (!sLow) return items;
    return items.filter(function (r) {
      if (!r) return false;
      var ref = String(r.section || r.section_ref || r.clause_ref || r.location || "").toLowerCase();
      if (!ref) return false;
      return ref.indexOf(sLow) !== -1 || sLow.indexOf(ref) !== -1;
    });
  }

  // ─── Channels ─────────────────────────────────────────────────────
  eli.register({
    tile: { app_legal_risks: function () { _open(); } },
    // Programmatic launch from legal_review's Launch Analysis.
    legal_risks: {
      run: _open,
      // Section-scoped read of the most recent legal-360 entry —
      // used by the selection panel's inline "Scan this section"
      // card. Returns a Promise<items[]> filtered to the section.
      filterForSection: function (sectionLabel) {
        if (!eli.activity || typeof eli.activity.list !== "function") return Promise.resolve([]);
        try {
          var entries = eli.activity.list({ limit: 50 }) || [];
          var hit = entries.filter(function (e) {
            return e && e.type === "legal-360" && e.payload;
          })[0];
          if (!hit) return Promise.resolve([]);
          var items = (hit.payload && hit.payload.items) || [];
          return Promise.resolve(_filterItemsForSection(items, sectionLabel));
        } catch (e) { return Promise.resolve([]); }
      },
    },
    // Activity-feed restore.
    activity_restore: { "legal-360": _restoreActivity },
  });

  // Back-compat shim for v2 callers that expect window.runDeal360Analysis.
  window.runDeal360Analysis = function () { _open(); };

  eli.log.event("tool", "legal_risks_initialized", {});
}

jsonTools.css:
/* legal_risks tool styles — port of v2 renderBalancedResults markup.
   Class-driven CSS replaces v2's inline-styles for maintainability.
   Injected as <style data-tool="legal_risks">. */

._eli3_lr_results {
  background: #f8f9fa;
  font-family: Inter, sans-serif;
  /* Mounts into #_eli3_dashboard_root which is `display: flex; flex-
   * direction: row` (built for sidebar|main). To take over the whole
   * tool window we need to fill the row's only child slot. flex:1 +
   * min-height:0 mirrors the kernel's .tool-panel primitive
   * (taskpane_v3.css §11) without coupling to that class name. */
  flex: 1 1 auto;
  width: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
}

/* ── Header ───────────────────────────────────────────────────────── */
._eli3_lr_results_header {
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  padding: 12px 15px;
  border-bottom: 3px solid #c9a227;
  margin-bottom: 15px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-shrink: 0;
}
._eli3_lr_results_title {
  font: 700 18px/1.1 Georgia, serif;
  color: #fff;
}
._eli3_lr_results_close {
  background: transparent;
  border: 0;
  font: 700 16px/1 'Inter', sans-serif;
  color: rgba(255, 255, 255, 0.85);
  cursor: pointer;
  padding: 2px 8px;
  transition: color 0.15s;
}
._eli3_lr_results_close:hover { color: #fff; }

/* ── Rules-active banner ──────────────────────────────────────────── */
._eli3_lr_results_rules_banner {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 8px 15px 8px;
  padding: 10px;
  background: #e8f5e9;
  border: 1px solid #c8e6c9;
  border-left: 5px solid #2e7d32;
}
._eli3_lr_results_rules_icon { font-size: 18px; }
._eli3_lr_results_rules_eyebrow {
  font: 800 10px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #1b5e20;
  margin-bottom: 2px;
}
._eli3_lr_results_rules_sub {
  font: 500 10px/1.3 'Inter', sans-serif;
  color: #2e7d32;
}

/* ── Issues Overview (collapsible) ────────────────────────────────── */
._eli3_lr_results_overview_head {
  cursor: pointer;
  margin: 0 14px 10px 14px;
  padding: 6px 10px;
  background: rgba(21, 101, 192, 0.08);
  border-left: 3px solid #1565c0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  user-select: none;
}
._eli3_lr_results_overview_label {
  font: 800 12px/1 'Inter', sans-serif;
  color: #1565c0;
  text-transform: uppercase;
  flex: 1;
}
._eli3_lr_results_overview_hint {
  font: 700 9px/1 'Inter', sans-serif;
  color: #1565c0;
  opacity: 0.6;
  letter-spacing: 1px;
  flex: 1;
  text-align: center;
  transition: opacity 0.2s;
  white-space: nowrap;
}
._eli3_lr_results_overview_arrow {
  font: 500 10px/1 'Inter', sans-serif;
  color: #1565c0;
  flex: 1;
  text-align: right;
}
._eli3_lr_results_overview_card {
  margin: 0 14px 15px 14px;
  padding: 15px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 5px solid #1565c0;
}
._eli3_lr_results_overview_title {
  font: 700 15px/1.3 'Inter', sans-serif;
  color: #1565c0;
  margin-bottom: 5px;
}
._eli3_lr_results_overview_balance {
  font: 500 13px/1.5 'Inter', sans-serif;
  color: #37474f;
}

/* ── Section header (Risks/Usage) ─────────────────────────────────── */
._eli3_lr_results_section_wrap {
  margin-bottom: 16px;
}
._eli3_lr_results_section_head {
  background: #c62828;
  padding: 10px 14px;
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  user-select: none;
}
._eli3_lr_results_section_icon { font-size: 15px; }
._eli3_lr_results_section_title {
  font: 800 13px/1 'Inter', sans-serif;
  color: #fff;
  letter-spacing: 0.3px;
  text-transform: uppercase;
}
._eli3_lr_results_section_count {
  background: rgba(255, 255, 255, 0.25);
  padding: 2px 8px;
  border-radius: 3px;
  font: 800 11px/1 'Inter', sans-serif;
  color: #fff;
}
._eli3_lr_results_section_arrow {
  margin-left: auto;
  font: 500 10px/1 'Inter', sans-serif;
  color: rgba(255, 255, 255, 0.7);
}
._eli3_lr_results_section_body {
  border: 1.5px solid #c62828;
  border-top: none;
  background: #fafbfc;
  padding: 12px 0;
}
._eli3_lr_results_section_body[hidden] { display: none; }

/* ── Empty-state inside section ───────────────────────────────────── */
._eli3_lr_results_empty {
  padding: 24px 16px;
  text-align: center;
}
._eli3_lr_results_empty_icon {
  font-size: 24px;
  margin-bottom: 8px;
}
._eli3_lr_results_empty_desc {
  font: 500 12px/1.4 'Inter', sans-serif;
  color: #94a3b8;
}

/* ── Risk/Usage card ──────────────────────────────────────────────── */
._eli3_lr_results_card {
  background: #fff;
  margin: 0 14px 12px 14px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  border: 2px solid #c62828;
  border-top: 4px solid #c62828;
  overflow: hidden;
}
._eli3_lr_results_card_eyebrow {
  text-align: center;
  padding: 5px 0;
  background: rgba(0, 0, 0, 0.02);
  border-bottom: 1px solid #f1f5f9;
  font: 800 9.5px/1 'Inter', sans-serif;
  letter-spacing: 1px;
  text-transform: uppercase;
}
._eli3_lr_results_card_body {
  padding: 12px;
}
._eli3_lr_results_card_head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px;
  margin-bottom: 6px;
}
._eli3_lr_results_card_num {
  font: 700 14px/1.4 'Inter', sans-serif;
  margin-right: 4px;
}
._eli3_lr_results_card_title {
  font: 700 14px/1.4 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_lr_results_card_ref {
  font: 400 10px/1.4 'Inter', sans-serif;
  color: #94a3b8;
  margin-left: 6px;
}
._eli3_lr_results_rule_badge {
  display: inline-block;
  margin-left: 6px;
  padding: 2px 6px;
  font: 700 9px/1 'Inter', sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  background: rgba(139, 92, 246, 0.12);
  color: #6d28d9;
  border: 1px solid rgba(139, 92, 246, 0.35);
  vertical-align: middle;
}
._eli3_lr_results_card_quote {
  font: italic 500 12px/1.4 'Georgia', serif;
  color: #546e7a;
  margin-bottom: 8px;
  background: #f9f9f9;
  padding: 6px 8px;
  border-radius: 3px;
}
._eli3_lr_results_card_analysis {
  font: 500 13px/1.5 'Inter', sans-serif;
  color: #333;
}
._eli3_lr_results_card_suggest {
  margin-top: 8px;
  background: #fff8e1;
  padding: 8px;
  border: 1px solid #ffe0b2;
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #e65100;
}
._eli3_lr_results_card_watchout {
  margin-top: 8px;
  background: #fff3cd;
  padding: 8px;
  border-left: 3px solid #ffc107;
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #856404;
}
._eli3_lr_results_card_actions {
  display: flex;
  gap: 5px;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px dashed #eee;
}

/* ── Card action buttons ──────────────────────────────────────────── */
._eli3_lr_results_btn {
  flex: 1;
  padding: 7px 8px;
  font: 800 10px/1 'Inter', sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  border: 1px solid #cbd5e1;
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  color: #475569;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_lr_results_btn:hover {
  border-color: #94a3b8;
  background: linear-gradient(180deg, #fff 0%, #e2e8f0 100%);
}
._eli3_lr_results_btn_locate:hover {
  border-color: #1565c0;
  color: #1565c0;
  background: #eff6ff;
}
._eli3_lr_results_btn_primary {
  flex: 1.4;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border-color: #0d47a1;
  box-shadow: 0 2px 6px rgba(21, 101, 192, 0.25);
}
._eli3_lr_results_btn_primary:hover {
  background: linear-gradient(135deg, #1d4ed8 0%, #1565c0 100%);
  border-color: #0d47a1;
}
._eli3_lr_results_btn_delete {
  background: linear-gradient(135deg, #c62828 0%, #8e1c1c 100%);
  border-color: #8e1c1c;
  box-shadow: 0 2px 6px rgba(198, 40, 40, 0.25);
}
._eli3_lr_results_btn_delete:hover {
  background: linear-gradient(135deg, #ef4444 0%, #c62828 100%);
  border-color: #8e1c1c;
}
._eli3_lr_results_btn_dismiss {
  flex: 0 0 30px;
  padding: 7px 4px;
  color: #94a3b8;
}
._eli3_lr_results_btn_dismiss:hover {
  border-color: #fca5a5;
  color: #b91c1c;
  background: #fef2f2;
}

/* ── Footer Home button ───────────────────────────────────────────── */
._eli3_lr_results_home {
  margin: 14px;
  padding: 10px 16px;
  font: 800 11px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  color: #475569;
  cursor: pointer;
  transition: all 0.15s;
  align-self: flex-start;
}
._eli3_lr_results_home:hover {
  border-color: #1565c0;
  color: #1565c0;
}
